parameters.functionCode:
// Carrega base de conhecimento dos .md em conhecimento/regras
const fs = require('fs');
const path = require('path');
const dir = $env.CONHECIMENTO_DIR || 'C:/Users/User/Desktop/native-agente/conhecimento/regras';
let base = '# BASE DE CONHECIMENTO — Georreferenciamento (INCRA/SIGEF)\n\n';
if (fs.existsSync(dir)) {
  for (const f of fs.readdirSync(dir).filter(x => x.endsWith('.md')).sort()) {
    base += fs.readFileSync(path.join(dir, f), 'utf8') + '\n\n---\n\n';
  }
}
return [{ json: { base, telefone: $json.phone, mensagem: $json.text?.message || $json.message, nome: $json.senderName } }];

